<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';require_method('GET');$u=current_user();$tenant=$u['tenant_id'];$member=$u['role']==='MEMBER';
if($member){
    $s=db()->prepare("SELECT (SELECT COUNT(*) FROM leads WHERE tenant_id=? AND (assigned_user_id=? OR created_by=?)) totalLeads,(SELECT COUNT(*) FROM leads WHERE tenant_id=? AND (assigned_user_id=? OR created_by=?) AND status NOT IN ('SEND_FAILED','BOUNCED','UNSUBSCRIBED')) validEmails,(SELECT COUNT(*) FROM campaigns WHERE tenant_id=? AND created_by=?) totalCampaigns,(SELECT COALESCE(SUM(sent_count),0) FROM campaigns WHERE tenant_id=? AND created_by=?) emailsSent,(SELECT COALESCE(SUM(pending_count),0) FROM campaigns WHERE tenant_id=? AND created_by=?) emailsPending,(SELECT COALESCE(SUM(failed_count),0) FROM campaigns WHERE tenant_id=? AND created_by=?) emailsFailed,(SELECT COUNT(*) FROM campaigns WHERE tenant_id=? AND created_by=? AND status IN ('QUEUED','RUNNING')) activeCampaigns,(SELECT COUNT(*) FROM smtp_accounts WHERE tenant_id=? AND is_active=1) smtpAccounts");
    $s->execute([$tenant,$u['id'],$u['id'],$tenant,$u['id'],$u['id'],$tenant,$u['id'],$tenant,$u['id'],$tenant,$u['id'],$tenant,$u['id'],$tenant,$u['id'],$tenant]);
}else{
    $s=db()->prepare("SELECT (SELECT COUNT(*) FROM leads WHERE tenant_id=?) totalLeads,(SELECT COUNT(*) FROM leads WHERE tenant_id=? AND status NOT IN ('SEND_FAILED','BOUNCED','UNSUBSCRIBED')) validEmails,(SELECT COUNT(*) FROM campaigns WHERE tenant_id=?) totalCampaigns,(SELECT COALESCE(SUM(sent_count),0) FROM campaigns WHERE tenant_id=?) emailsSent,(SELECT COALESCE(SUM(pending_count),0) FROM campaigns WHERE tenant_id=?) emailsPending,(SELECT COALESCE(SUM(failed_count),0) FROM campaigns WHERE tenant_id=?) emailsFailed,(SELECT COUNT(*) FROM campaigns WHERE tenant_id=? AND status IN ('QUEUED','RUNNING')) activeCampaigns,(SELECT COUNT(*) FROM smtp_accounts WHERE tenant_id=? AND is_active=1) smtpAccounts");$s->execute(array_fill(0,8,$tenant));
}
$stats=$s->fetch();$logWhere=$member?' AND c.created_by=?':'';$a=db()->prepare("SELECT DATE_FORMAT(l.created_at,'%a') day,SUM(l.status='SENT') sent,0 opened,SUM(l.status='FAILED') failed FROM email_logs l JOIN campaigns c ON c.id=l.campaign_id AND c.tenant_id=l.tenant_id WHERE l.tenant_id=?{$logWhere} AND l.created_at>=UTC_DATE()-INTERVAL 6 DAY GROUP BY DATE(l.created_at) ORDER BY DATE(l.created_at)");$a->execute($member?[$tenant,$u['id']]:[$tenant]);$leadWhere=$member?' AND (assigned_user_id=? OR created_by=?)':'';$g=db()->prepare("SELECT DATE_FORMAT(created_at,'%b') month,COUNT(*) leads FROM leads WHERE tenant_id=?{$leadWhere} AND created_at>=UTC_DATE()-INTERVAL 6 MONTH GROUP BY YEAR(created_at),MONTH(created_at) ORDER BY YEAR(created_at),MONTH(created_at)");$g->execute($member?[$tenant,$u['id'],$u['id']]:[$tenant]);$campaignWhere=$member?' AND created_by=?':'';$c=db()->prepare("SELECT public_id id,name,status,total_recipients recipients,sent_count sent,failed_count failed,pending_count pending FROM campaigns WHERE tenant_id=?{$campaignWhere} ORDER BY created_at DESC LIMIT 5");$c->execute($member?[$tenant,$u['id']]:[$tenant]);$f=db()->prepare("SELECT COALESCE(r.failure_category,'OTHER') category,COUNT(*) count FROM campaign_recipients r JOIN campaigns c ON c.tenant_id=r.tenant_id AND c.id=r.campaign_id WHERE r.tenant_id=? AND r.status='FAILED'{$campaignWhere} GROUP BY COALESCE(r.failure_category,'OTHER') ORDER BY count DESC");$f->execute($member?[$tenant,$u['id']]:[$tenant]);respond(['stats'=>$stats,'failureBreakdown'=>$f->fetchAll(),'emailActivity'=>$a->fetchAll(),'leadGrowth'=>$g->fetchAll(),'recentCampaigns'=>$c->fetchAll()]);
